{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성의 손에 두 개의 물잔이 들려 있음."
    },
    {
      "id": "R2",
      "summary_ko": "여성이 걸레를 집어 올릴 때 걸레가 나타났다가 사라짐."
    },
    {
      "id": "R3",
      "summary_ko": "두 잔의 물을 마신 후 청소를 시작하며, 한 잔을 내려놓자마자 사라짐."
    },
    {
      "id": "R4",
      "summary_ko": "유리잔이 창문 닦는 걸레/와이프로 변함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "카운터 위의 물잔이 사라짐."
    },
    {
      "id": "C2",
      "summary_ko": "카운터에 내려놓던 유리잔이 변형 및 복제된 후 완전히 사라지고 손에 걸레가 나타남."
    },
    {
      "id": "C3",
      "summary_ko": "사라진 유리잔이나 여성의 손에서 청소용 걸레가 카운터 위로 애매하게 생성됨."
    },
    {
      "id": "C4",
      "summary_ko": "분무기 노즐과 손잡이가 다루어지는 동안 형태가 일관되지 않게 일그러짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 손에 들려 있는 두 개의 유리잔을 단순히 언급하는 반면, C1은 카운터 위의 유리잔이 사라지는 현상을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R1은 손에 있는 유리잔에 대한 언급이나, C2는 유리잔이 내려놓아지며 변형 및 소멸하는 복합적인 이상 현상을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 손에 든 잔에 대한 내용이고, C3은 걸레가 나타나는 현상을 설명합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상이 유리잔과 분무기로 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 걸레가 나타났다가 사라지는 현상이고, C1은 유리잔이 사라지는 현상입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "C2에 걸레가 나타나는 내용이 일부 포함되어 있으나, R2의 주된 현상(집어 올릴 때 나타났다가 사라짐)과 동일한 결함인지 불명확합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "uncertain",
      "reason_ko": "둘 다 걸레가 나타나는 이상 현상을 다루고 있으나, 발생 상황 및 사라짐 여부 등의 설명이 일부만 겹쳐 동일한 현상인지 단정하기 어렵습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상이 걸레와 분무기로 서로 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "카운터에 내려놓은 유리잔이 사라지는 동일한 현상을 설명하고 있습니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "유리잔을 내려놓을 때 해당 잔이 사라진다는 핵심 결함과 대상이 일치합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R3은 유리잔의 소멸에 집중하는 반면, C3은 걸레가 물질화되어 나타나는 현상을 주 대상으로 설명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상이 유리잔과 분무기로 다릅니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R4는 잔이 닦개로 변형되는 현상이고, C1은 잔이 단순히 사라지는 현상입니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "유리잔이 변형/소멸되면서 걸레/닦개로 변하거나 교체되는 동일한 모핑 현상을 다루고 있습니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C3",
      "verdict": "same",
      "reason_ko": "유리잔으로부터 걸레/닦개가 변형되어 생성되는 동일한 현상을 다루고 있습니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "대상이 유리잔/걸레와 분무기로 서로 다릅니다."
    }
  ]
}
